inline void assert_wire_equals(const uint8_t* expected, size_t expected_len,
                               const rnet::WireFrame& actual, const char* name) {
  TEST_ASSERT_EQUAL_size_t_MESSAGE(expected_len, actual.len, name);
  TEST_ASSERT_EQUAL_HEX8_ARRAY_MESSAGE(expected, actual.bytes, expected_len, name);
}

// Feeds bytes and returns the result of the last byte.
inline rnet::ParseResult feed_all(rnet::FrameParser& p, const uint8_t* bytes, size_t len) {
  rnet::ParseResult last = rnet::ParseResult::kNone;
  for (size_t i = 0; i < len; ++i) {
    last = p.feed(bytes[i]);
  }
  return last;
}
